330	// sourceDeclarationProblems says what is wrong with the link between migrated
331	// views and the sources scanned for them, empty when it is fine. files are the
332	// paths relative to internal/ of every non-test source file.
333	func sourceDeclarationProblems(migrated map[command.ViewType][]string, sources map[command.ViewType][]string, files []string) []string {
334		var problems []string
335		for vt := range migrated {
336			if len(sources[vt]) == 0 {
337				problems = append(problems, fmt.Sprintf("view %q is migrated but declares no source to scan in migratedSources", vt))
338			}
339		}
340		for vt, prefixes := range sources {
341			if len(migrated[vt]) == 0 {
342				problems = append(problems, fmt.Sprintf("view %q has sources in migratedSources but is not migrated (migratedTables)", vt))
343			}
344			for _, p := range prefixes {
345				if !anyHasPrefix(files, p) {
346					problems = append(problems, fmt.Sprintf("view %q: source prefix %q matches no file", vt, p))
347				}
348			}
349		}
350		sort.Strings(problems)
351		return problems
352	}
353	
354	func anyHasPrefix(files []string, prefix string) bool {
355		for _, f := range files {
356			if prefix != "" && strings.HasPrefix(f, prefix) {
357				return true
358			}
359		}
360		return false
361	}
