363	// Criteria 2b and 6: the sources scanned are exactly those of the migrated views.
364	func TestActivityGuardMigratedSourcesAreDeclared(t *testing.T) {
365		var files []string
366		sourceFiles(t, func(rel string, _ *token.FileSet, _ *ast.File) { files = append(files, rel) })
367		for _, p := range sourceDeclarationProblems(migratedTables, migratedSources, files) {
368			t.Error(p)
369		}
370	}
