372	// The logic itself, on fictitious views and files.
373	func TestActivityGuardMigratedSourcesLogic(t *testing.T) {
374		const v command.ViewType = "fiction"
375		files := []string{"ui/jobsview/model.go", "ui/oci/a.go", "ui/oci/b.go"}
376		tests := []struct {
377			name     string
378			migrated map[command.ViewType][]string
379			sources  map[command.ViewType][]string
380			want     []string // substrings, one per expected problem
381		}{
382			{"jobs passes", map[command.ViewType][]string{command.ViewJobs: {"jobs/runs"}}, map[command.ViewType][]string{command.ViewJobs: {"ui/jobsview/"}}, nil},
383			{"file prefix passes", map[command.ViewType][]string{v: {"x"}}, map[command.ViewType][]string{v: {"ui/oci/a.go"}}, nil},
384			{"migrated view without sources", map[command.ViewType][]string{v: {"x"}}, nil, []string{`view "fiction" is migrated but declares no source`}},
385			{"sources without migrated view", nil, map[command.ViewType][]string{v: {"ui/oci/"}}, []string{`view "fiction" has sources`}},
386			{"prefix matching nothing", map[command.ViewType][]string{v: {"x"}}, map[command.ViewType][]string{v: {"ui/nowhere/"}}, []string{`"ui/nowhere/" matches no file`}},
387			{"empty prefix matches nothing", map[command.ViewType][]string{v: {"x"}}, map[command.ViewType][]string{v: {""}}, []string{`"" matches no file`}},
388		}
389		for _, tt := range tests {
390			t.Run(tt.name, func(t *testing.T) {
391				got := sourceDeclarationProblems(tt.migrated, tt.sources, files)
392				if len(got) != len(tt.want) {
393					t.Fatalf("problems = %v, want %d", got, len(tt.want))
394				}
395				for i, w := range tt.want {
396					if !strings.Contains(got[i], w) {
397						t.Errorf("problem %d = %q, want it to contain %q", i, got[i], w)
398					}
399				}
400			})
401		}
402	}
