404	// activityGlyphs are the runes of internal/ui/indicator; a view takes them from
405	// indicator.Glyph and never spells one.
406	const activityGlyphs = "●○◴⊗◐◕◉⊘⊖◌"
407	
408	// declaredViewTicks are the tea.Tick / tea.Every calls a migrated view may
409	// still make, keyed "<file relative to internal/>:<function>" with the reason.
410	// Empty today: the router's one tick animates every row (DEVDESK-139). The list
411	// may only shrink.
412	var declaredViewTicks = map[string]string{}
413	
414	// declaredGlyphConstants are the constants a migrated view may still define with
415	// an activity glyph in them, keyed "<file relative to internal/>:<constant>" with
416	// the reason (DEVDESK-144, decision Q4-A). The exception is the constant, not the
417	// file: any other literal in the same file is still rejected, so the help text
418	// has to build its sentence from the constant. The list may only shrink.
419	var declaredGlyphConstants = map[string]string{
420		"ui/workspaces/view.go:gitMarkNoUpstream": "git marker for a branch with no upstream; it is a git fact, not a row state, and ws never shows the cancelled state, so nothing on screen is ambiguous (changing the marker is a UX ticket of its own)",
421	}
