423	// finding is one retired mechanism found in a source file.
424	type finding struct {
425		Pos  token.Position // file:line:column
426		What string
427	}
428	
429	// bubbleTeaName returns the local name file gives the bubbletea import: its
430	// alias, "." for a dot import, "tea" when unnamed, or "" when the file does not
431	// import it (or blank-imports it). A different package that happens to be
432	// called tea is therefore not mistaken for it.
433	func bubbleTeaName(file *ast.File) string {
434		for _, imp := range file.Imports {
435			path, err := strconv.Unquote(imp.Path.Value)
436			if err != nil || path != "github.com/charmbracelet/bubbletea" {
437				continue
438			}
439			switch {
440			case imp.Name == nil:
441				return "tea"
442			case imp.Name.Name == "_":
443				return ""
444			default:
445				return imp.Name.Name
446			}
447		}
448		return ""
449	}
450	
451	// retiredMechanisms reports, in a migrated view's file, every retired
452	// mechanism: AdvanceSpinner, a StatusColumn: key, a frame field, an activity
453	// glyph literal, and any reference to bubbletea's Tick / Every (under whatever name the file
454	// imports it) outside declaredViewTicks.
455	// rel is the file's path relative to internal/; it is the key of a declared tick.
456	// RenderedFrame (a method of the viewport frame) is allowed.
457	func retiredMechanisms(fset *token.FileSet, file *ast.File, rel string) []finding {
458		var out []finding
459		report := func(pos token.Pos, what string) {
460			out = append(out, finding{Pos: fset.Position(pos), What: what})
461		}
462		tea := bubbleTeaName(file)
463		selectors := map[*ast.Ident]bool{} // identifiers seen as the Sel of a selector
464		// reportTick flags any reference to bubbletea's Tick / Every, called or not
465		// (`var tick = tea.Tick` is as much a tick as `tea.Tick(...)`), unless the
466		// enclosing "<file>:<function>" is declared.
467		reportTick := func(pos token.Pos, fn, name string) {
468			if name != "Tick" && name != "Every" {
469				return
470			}
471			if _, declared := declaredViewTicks[rel+":"+fn]; !declared {
472				report(pos, "reference to bubbletea's "+name+" (a view's rows are animated by the router's tick)")
473			}
474		}
475		isFrame := func(name string) bool {
476			return name == "Frame" || name == "frame" || name == "SpinnerFrame"
477		}
478		visit := func(fn string) func(ast.Node) bool {
479			return func(n ast.Node) bool {
480				switch x := n.(type) {
481				case *ast.CallExpr:
482					sel, ok := x.Fun.(*ast.SelectorExpr)
483					if !ok {
484						break
485					}
486					if sel.Sel.Name == "AdvanceSpinner" {
487						report(x.Pos(), "call to AdvanceSpinner")
488					}
489				case *ast.KeyValueExpr:
490					if id, ok := x.Key.(*ast.Ident); ok {
491						if id.Name == "StatusColumn" {
492							report(id.Pos(), "StatusColumn: key")
493						}
494						if isFrame(id.Name) {
495							report(id.Pos(), "frame field "+id.Name+": set")
496						}
497					}
498				case *ast.Field:
499					for _, id := range x.Names {
500						if isFrame(id.Name) {
501							report(id.Pos(), "frame field "+id.Name)
502						}
503					}
504				case *ast.Ident:
505					// Dot import: a bare Tick / Every that no declaration in the file binds.
506					if tea == "." && x.Obj == nil && !selectors[x] {
507						reportTick(x.Pos(), fn, x.Name)
508					}
509				case *ast.SelectorExpr:
510					selectors[x.Sel] = true
511					if pkg, ok := x.X.(*ast.Ident); ok && tea != "" && tea != "." && pkg.Name == tea {
512						reportTick(x.Pos(), fn, x.Sel.Name)
513					}
514					if isFrame(x.Sel.Name) {
515						report(x.Sel.Pos(), "frame selector ."+x.Sel.Name)
516					}
517				case *ast.BasicLit:
518					if x.Kind == token.STRING || x.Kind == token.CHAR {
519						s, err := strconv.Unquote(x.Value)
520						if x.Kind == token.CHAR {
521							var q rune
522							q, _, _, err = strconv.UnquoteChar(x.Value[1:len(x.Value)-1], '\'')
523							s = string(q)
524						}
525						if err == nil && strings.ContainsAny(s, activityGlyphs) {
526							report(x.Pos(), "activity glyph written as a literal "+x.Value+" (use indicator.Glyph)")
527						}
528					}
529				}
530				return true
531			}
532		}
533		for _, decl := range file.Decls {
534			fn := ""
535			if fd, ok := decl.(*ast.FuncDecl); ok {
536				fn = fd.Name.Name
537			}
538			if gd, ok := decl.(*ast.GenDecl); ok && gd.Tok == token.CONST {
539				for _, spec := range gd.Specs {
540					if isDeclaredGlyphConstant(rel, spec) {
541						continue
542					}
543					ast.Inspect(spec, visit(fn))
544				}
545				continue
546			}
547			ast.Inspect(decl, visit(fn))
548		}
549		return out
550	}
551	
552	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
553	// declaredGlyphConstants for the file rel.
554	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
555		vs, ok := spec.(*ast.ValueSpec)
556		if !ok || len(vs.Names) == 0 {
557			return false
558		}
559		for _, id := range vs.Names {
560			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
561				return false
562			}
563		}
564		return true
565	}
566	
567	// Criterion 2a/2b: no retired mechanism and no tick in a migrated view.
568	func TestActivityGuardMigratedSourcesUseNoRetiredMechanism(t *testing.T) {
569		scanned := 0
570		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
571			if !hasAnyPrefix(rel, allMigratedSources()) {
572				return
573			}
574			scanned++
575			for _, f := range retiredMechanisms(fset, file, rel) {
576				t.Errorf("%s: %s in a migrated view (A-16 criterion 2/3)", f.Pos, f.What)
577			}
578		})
579		if scanned == 0 {
580			t.Fatalf("no source file found under %v: the scan reads nothing", migratedSources)
581		}
582		for key, reason := range declaredViewTicks {
583			if reason == "" {
584				t.Errorf("declared view tick %q names no reason", key)
585			}
586		}
587		for key, reason := range declaredGlyphConstants {
588			if reason == "" {
589				t.Errorf("declared glyph constant %q names no reason", key)
590			}
591		}
592	}
593	
594	// A declared glyph constant must still exist and still hold a glyph, otherwise
595	// the exception is stale and must go; and it excuses that constant only.
596	func TestActivityGuardDeclaredGlyphConstantsAreLive(t *testing.T) {
597		live := map[string]bool{}
598		sourceFiles(t, func(rel string, fset *token.FileSet, file *ast.File) {
599			for _, decl := range file.Decls {
600				gd, ok := decl.(*ast.GenDecl)
601				if !ok || gd.Tok != token.CONST {
602					continue
603				}
604				for _, spec := range gd.Specs {
605					vs, ok := spec.(*ast.ValueSpec)
606					if !ok {
607						continue
608					}
609					for i, id := range vs.Names {
610						key := rel + ":" + id.Name
611						if _, declared := declaredGlyphConstants[key]; !declared || i >= len(vs.Values) {
612							continue
613						}
614						if lit, ok := vs.Values[i].(*ast.BasicLit); ok {
615							s, _ := strconv.Unquote(lit.Value)
616							live[key] = strings.ContainsAny(s, activityGlyphs)
617						}
618					}
619				}
620			}
621		})
622		for key := range declaredGlyphConstants {
623			if !live[key] {
624				t.Errorf("declared glyph constant %q does not exist or holds no activity glyph: remove the exception", key)
625			}
626		}
627		if got := len(declaredGlyphConstants); got > 1 {
628			t.Errorf("declaredGlyphConstants has %d entries, ceiling is 1: the list may only shrink", got)
629		}
630	}
631	
632	// The exception covers the constant and nothing else in the file.
633	func TestActivityGuardGlyphConstantExceptionIsNarrow(t *testing.T) {
634		src := "package v\nconst gitMarkNoUpstream = \"\u2298\"\nconst other = \"\u2298\"\nvar help = \"a \u2298 b\"\n"
635		fset := token.NewFileSet()
636		file, err := parser.ParseFile(fset, "view.go", src, 0)
637		if err != nil {
638			t.Fatal(err)
639		}
640		got := retiredMechanisms(fset, file, "ui/workspaces/view.go")
641		if len(got) != 2 {
642			t.Fatalf("findings = %v, want the undeclared const and the var literal only", got)
643		}
644		for _, f := range got {
645			if f.Pos.Line == 2 {
646				t.Errorf("the declared constant was flagged: %v", f)
647			}
648		}
649	}
650	
651	// The detection itself, on sources held in strings.
652	func TestActivityGuardRetiredMechanismsLogic(t *testing.T) {
653		const head = "package v\nimport tea \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
654		const (
655			bt    = "package v\nimport bt \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
656			dot   = "package v\nimport . \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
657			other = "package v\nimport tea \"example.com/notbubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
658		)
659		tests := []struct {
660			name     string
661			head     string // import block overriding head; it must keep the same 3 lines
662			body     string
663			declared map[string]string
664			want     int
665			at       string // "line:column" of the first finding, when want > 0
666		}{
667			{"tea.Tick", "", "func f() { _ = tea.Tick(0, nil) }", nil, 1, "4:16"},
668			{"tea.Every", "", "func f() { _ = tea.Every(0, nil) }", nil, 1, "4:16"},
669			{"spinner.Tick is not a view tick", "", "func f() { _ = spinner.Tick }\nfunc g() { _ = spinner.Tick() }", nil, 0, ""},
670			{"declared tick", "", "func f() { _ = tea.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 0, ""},
671			{"tick declared for another function", "", "func g() { _ = tea.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 1, "4:16"},
672			{"AdvanceSpinner", "", "func f(t T) { t.AdvanceSpinner() }", nil, 1, "4:15"},
673			{"glyph literal", "", "var g = \"\u25cf\"", nil, 1, "4:9"},
674			{"clean", "", "func f() {}", nil, 0, ""},
675			{"aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", nil, 1, "4:16"},
676			{"dot import", dot, "func f() { _ = Tick(0, nil) }", nil, 1, "4:16"},
677			{"dot import, bare reference", dot, "var tick = Every", nil, 1, "4:12"},
678			{"package variable holding tea.Tick", "", "var tick = tea.Tick", nil, 1, "4:12"},
679			{"tick in a method", "", "func (m M) f() { _ = tea.Tick(0, nil) }", nil, 1, "4:22"},
680			{"declared tick, aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 0, ""},
681			{"non-bubbletea package named tea", other, "func f() { _ = tea.Tick(0, nil) }", nil, 0, ""},
682			{"dot import does not flag a method named Tick", dot, "func f(t T) { t.Tick() }", nil, 0, ""},
683		}
684		for _, tt := range tests {
685			t.Run(tt.name, func(t *testing.T) {
686				old := declaredViewTicks
687				declaredViewTicks = tt.declared
688				defer func() { declaredViewTicks = old }()
689				fset := token.NewFileSet()
690				h := head
691				if tt.head != "" {
692					h = tt.head
693				}
694				src := h + tt.body
695				file, err := parser.ParseFile(fset, "v.go", src, 0)
696				if err != nil {
697					t.Fatal(err)
698				}
699				got := retiredMechanisms(fset, file, "ui/v/v.go")
700				if len(got) != tt.want {
701					t.Fatalf("findings = %v, want %d", got, tt.want)
702				}
703				if tt.want > 0 {
704					if at := fmt.Sprintf("%d:%d", got[0].Pos.Line, got[0].Pos.Column); at != tt.at {
705						t.Errorf("first finding at %s, want %s", at, tt.at)
706					}
707				}
708			})
709		}
710	}
711	
712	func allMigratedSources() []string {
713		var out []string
714		for _, prefixes := range migratedSources {
715			out = append(out, prefixes...)
716		}
717		return out
718	}
719	
720	func hasAnyPrefix(s string, prefixes []string) bool {
721		for _, p := range prefixes {
722			if strings.HasPrefix(s, p) {
723				return true
724			}
725		}
726		return false
727	}
728	
729	func contains(list []string, s string) bool {
730		for _, x := range list {
731			if x == s {
732				return true
733			}
734		}
735		return false
736	}
737	
738	func sortedKeys(m map[string]datatable.ActivityTable) []string {
739		out := make([]string, 0, len(m))
740		for k := range m {
741			out = append(out, k)
742		}
743		sort.Strings(out)
744		return out
745	}
746	
747	// footerRenderer is what a view exposes for its footer (the router's contract,
748	// restated so the guard reads it without the router).
749	type footerRenderer interface {
750		RenderFooter(width int) string
751	}
752	
753	// migratedFooterSeeds put a migrated view on screen with one active row selected
754	// and return the state that row is in. A migrated view without a seed fails the
755	// guard by name.
756	var migratedFooterSeeds = map[command.ViewType]func(*testing.T, *App) indicator.State{
757		command.ViewJobs:       seedJobsFooter,
758		command.ViewWorkspaces: seedWorkspacesFooter,
759		command.ViewSecurity:   seedSecurityFooter,
760	}
761	
762	// seedJobsFooter starts a scan run, moves its item to running (a started run
763	// is queued until a transition says otherwise), and opens :jobs, whose first run
764	// is selected.
765	func seedJobsFooter(t *testing.T, a *App) indicator.State {
766		t.Helper()
767		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
768		snap := a.jobs.Snapshot()
769		if len(snap) != 1 || !a.jobs.Advance(snap[0].ID, "a", jobs.ItemRunning, "") {
770			t.Fatalf("the seed could not put the run's item in the running state: %+v", snap)
771		}
772		testutil.Msgs(a.switchView(command.ViewJobs))
773		a.resize(a.width, a.height)
774		return indicator.Running
775	}
776	
777	// footerSeedProblems says which migrated views have no seed, and which seeds
778	// belong to no migrated view.
779	func footerSeedProblems(migrated map[command.ViewType][]string, seeds map[command.ViewType]func(*testing.T, *App) indicator.State) []string {
780		var problems []string
781		for vt := range migrated {
782			if seeds[vt] == nil {
783				problems = append(problems, fmt.Sprintf("view %q is migrated but has no entry in migratedFooterSeeds", vt))
784			}
785		}
786		for vt := range seeds {
787			if len(migrated[vt]) == 0 {
788				problems = append(problems, fmt.Sprintf("view %q has a footer seed but is not migrated", vt))
789			}
790		}
791		sort.Strings(problems)
792		return problems
793	}
794	
795	// footerGlyphProblem is empty when footer carries the glyph of state. The footer
796	// glyph never blinks, so the steady one (on = true) is the one to look for.
797	func footerGlyphProblem(footer string, state indicator.State) string {
798		glyph := indicator.Glyph(state, true)
799		if glyph == "" {
800			return fmt.Sprintf("state %v has no glyph: the seed must put the row in a visible state", state)
801		}
802		if !strings.Contains(ansi.Strip(footer), glyph) {
803			return fmt.Sprintf("the footer does not carry the glyph %q of state %v", glyph, state)
804		}
805		return ""
806	}
807	
808	// Criterion 5, footer half: the selected row's footer says its state with the
809	// same glyph as the column.
810	func TestActivityGuardMigratedFooterCarriesTheRowGlyph(t *testing.T) {
811		for _, p := range footerSeedProblems(migratedTables, migratedFooterSeeds) {
812			t.Error(p)
813		}
814		for vt, seed := range migratedFooterSeeds {
815			if seed == nil || len(migratedTables[vt]) == 0 {
816				continue
817			}
818			t.Run(string(vt), func(t *testing.T) {
819				a := routerAt(t, &bareView{}, 180, 40)
820				state := seed(t, a)
821				fr, ok := a.views[vt].(footerRenderer)
822				if !ok {
823					t.Fatalf("view %q is migrated but is a %T, which renders no footer", vt, a.views[vt])
824				}
825				if msg := footerGlyphProblem(fr.RenderFooter(120), state); msg != "" {
826					t.Errorf("view %q: %s (A-16 criterion 5)\n%s", vt, msg, ansi.Strip(fr.RenderFooter(120)))
827				}
828			})
829		}
830	}
831	
832	// The footer logic, on fictitious data.
833	func TestActivityGuardFooterLogic(t *testing.T) {
834		seed := func(*testing.T, *App) indicator.State { return indicator.Running }
835		const v command.ViewType = "fiction"
836		mig := map[command.ViewType][]string{v: {"x"}}
837	
838		if got := footerSeedProblems(mig, nil); len(got) != 1 || !strings.Contains(got[0], `"fiction"`) {
839			t.Errorf("a migrated view without a seed: %v", got)
840		}
841		if got := footerSeedProblems(nil, map[command.ViewType]func(*testing.T, *App) indicator.State{v: seed}); len(got) != 1 {
842			t.Errorf("a seed without a migrated view: %v", got)
843		}
844		if got := footerSeedProblems(mig, map[command.ViewType]func(*testing.T, *App) indicator.State{v: seed}); len(got) != 0 {
845			t.Errorf("a seeded migrated view: %v", got)
846		}
847	
848		run := indicator.Glyph(indicator.Running, true)
849		if msg := footerGlyphProblem("  Scanning "+run+" a", indicator.Running); msg != "" {
850			t.Errorf("a footer with the glyph: %s", msg)
851		}
852		if msg := footerGlyphProblem("  1 job running", indicator.Running); msg == "" {
853			t.Error("a footer without the glyph passed")
854		}
855		if msg := footerGlyphProblem("anything", indicator.Idle); msg == "" {
856			t.Error("an idle seed passed: it has no glyph to look for")
857		}
858	}
