552	// isDeclaredGlyphConstant reports whether spec defines only constants declared in
553	// declaredGlyphConstants for the file rel.
554	func isDeclaredGlyphConstant(rel string, spec ast.Spec) bool {
555		vs, ok := spec.(*ast.ValueSpec)
556		if !ok || len(vs.Names) == 0 {
557			return false
558		}
559		for _, id := range vs.Names {
560			if _, declared := declaredGlyphConstants[rel+":"+id.Name]; !declared {
561				return false
562			}
563		}
564		return true
565	}
