651	// The detection itself, on sources held in strings.
652	func TestActivityGuardRetiredMechanismsLogic(t *testing.T) {
653		const head = "package v\nimport tea \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
654		const (
655			bt    = "package v\nimport bt \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
656			dot   = "package v\nimport . \"github.com/charmbracelet/bubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
657			other = "package v\nimport tea \"example.com/notbubbletea\"\nimport \"github.com/charmbracelet/bubbles/spinner\"\n"
658		)
659		tests := []struct {
660			name     string
661			head     string // import block overriding head; it must keep the same 3 lines
662			body     string
663			declared map[string]string
664			want     int
665			at       string // "line:column" of the first finding, when want > 0
666		}{
667			{"tea.Tick", "", "func f() { _ = tea.Tick(0, nil) }", nil, 1, "4:16"},
668			{"tea.Every", "", "func f() { _ = tea.Every(0, nil) }", nil, 1, "4:16"},
669			{"spinner.Tick is not a view tick", "", "func f() { _ = spinner.Tick }\nfunc g() { _ = spinner.Tick() }", nil, 0, ""},
670			{"declared tick", "", "func f() { _ = tea.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 0, ""},
671			{"tick declared for another function", "", "func g() { _ = tea.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 1, "4:16"},
672			{"AdvanceSpinner", "", "func f(t T) { t.AdvanceSpinner() }", nil, 1, "4:15"},
673			{"glyph literal", "", "var g = \"\u25cf\"", nil, 1, "4:9"},
674			{"clean", "", "func f() {}", nil, 0, ""},
675			{"aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", nil, 1, "4:16"},
676			{"dot import", dot, "func f() { _ = Tick(0, nil) }", nil, 1, "4:16"},
677			{"dot import, bare reference", dot, "var tick = Every", nil, 1, "4:12"},
678			{"package variable holding tea.Tick", "", "var tick = tea.Tick", nil, 1, "4:12"},
679			{"tick in a method", "", "func (m M) f() { _ = tea.Tick(0, nil) }", nil, 1, "4:22"},
680			{"declared tick, aliased import", bt, "func f() { _ = bt.Tick(0, nil) }", map[string]string{"ui/v/v.go:f": "why"}, 0, ""},
681			{"non-bubbletea package named tea", other, "func f() { _ = tea.Tick(0, nil) }", nil, 0, ""},
682			{"dot import does not flag a method named Tick", dot, "func f(t T) { t.Tick() }", nil, 0, ""},
683		}
684		for _, tt := range tests {
685			t.Run(tt.name, func(t *testing.T) {
686				old := declaredViewTicks
687				declaredViewTicks = tt.declared
688				defer func() { declaredViewTicks = old }()
689				fset := token.NewFileSet()
690				h := head
691				if tt.head != "" {
692					h = tt.head
693				}
694				src := h + tt.body
695				file, err := parser.ParseFile(fset, "v.go", src, 0)
696				if err != nil {
697					t.Fatal(err)
698				}
699				got := retiredMechanisms(fset, file, "ui/v/v.go")
700				if len(got) != tt.want {
701					t.Fatalf("findings = %v, want %d", got, tt.want)
702				}
703				if tt.want > 0 {
704					if at := fmt.Sprintf("%d:%d", got[0].Pos.Line, got[0].Pos.Column); at != tt.at {
705						t.Errorf("first finding at %s, want %s", at, tt.at)
706					}
707				}
708			})
709		}
710	}
