729	func contains(list []string, s string) bool {
730		for _, x := range list {
731			if x == s {
732				return true
733			}
734		}
735		return false
736	}
737	
738	func sortedKeys(m map[string]datatable.ActivityTable) []string {
739		out := make([]string, 0, len(m))
740		for k := range m {
741			out = append(out, k)
742		}
743		sort.Strings(out)
744		return out
745	}
746	
747	// footerRenderer is what a view exposes for its footer (the router's contract,
748	// restated so the guard reads it without the router).
749	type footerRenderer interface {
750		RenderFooter(width int) string
751	}
752	
753	// migratedFooterSeeds put a migrated view on screen with one active row selected
754	// and return the state that row is in. A migrated view without a seed fails the
755	// guard by name.
756	var migratedFooterSeeds = map[command.ViewType]func(*testing.T, *App) indicator.State{
757		command.ViewJobs:       seedJobsFooter,
758		command.ViewWorkspaces: seedWorkspacesFooter,
759		command.ViewSecurity:   seedSecurityFooter,
760	}
761	
762	// seedJobsFooter starts a scan run, moves its item to running (a started run
763	// is queued until a transition says otherwise), and opens :jobs, whose first run
764	// is selected.
765	func seedJobsFooter(t *testing.T, a *App) indicator.State {
766		t.Helper()
767		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
768		snap := a.jobs.Snapshot()
769		if len(snap) != 1 || !a.jobs.Advance(snap[0].ID, "a", jobs.ItemRunning, "") {
770			t.Fatalf("the seed could not put the run's item in the running state: %+v", snap)
771		}
772		testutil.Msgs(a.switchView(command.ViewJobs))
773		a.resize(a.width, a.height)
774		return indicator.Running
775	}
776	
777	// footerSeedProblems says which migrated views have no seed, and which seeds
778	// belong to no migrated view.
779	func footerSeedProblems(migrated map[command.ViewType][]string, seeds map[command.ViewType]func(*testing.T, *App) indicator.State) []string {
780		var problems []string
781		for vt := range migrated {
782			if seeds[vt] == nil {
783				problems = append(problems, fmt.Sprintf("view %q is migrated but has no entry in migratedFooterSeeds", vt))
784			}
785		}
786		for vt := range seeds {
787			if len(migrated[vt]) == 0 {
788				problems = append(problems, fmt.Sprintf("view %q has a footer seed but is not migrated", vt))
789			}
790		}
791		sort.Strings(problems)
792		return problems
793	}
794	
795	// footerGlyphProblem is empty when footer carries the glyph of state. The footer
796	// glyph never blinks, so the steady one (on = true) is the one to look for.
797	func footerGlyphProblem(footer string, state indicator.State) string {
798		glyph := indicator.Glyph(state, true)
799		if glyph == "" {
800			return fmt.Sprintf("state %v has no glyph: the seed must put the row in a visible state", state)
801		}
802		if !strings.Contains(ansi.Strip(footer), glyph) {
803			return fmt.Sprintf("the footer does not carry the glyph %q of state %v", glyph, state)
804		}
805		return ""
806	}
807	
808	// Criterion 5, footer half: the selected row's footer says its state with the
809	// same glyph as the column.
810	func TestActivityGuardMigratedFooterCarriesTheRowGlyph(t *testing.T) {
811		for _, p := range footerSeedProblems(migratedTables, migratedFooterSeeds) {
812			t.Error(p)
813		}
814		for vt, seed := range migratedFooterSeeds {
815			if seed == nil || len(migratedTables[vt]) == 0 {
816				continue
817			}
818			t.Run(string(vt), func(t *testing.T) {
819				a := routerAt(t, &bareView{}, 180, 40)
820				state := seed(t, a)
821				fr, ok := a.views[vt].(footerRenderer)
822				if !ok {
823					t.Fatalf("view %q is migrated but is a %T, which renders no footer", vt, a.views[vt])
824				}
825				if msg := footerGlyphProblem(fr.RenderFooter(120), state); msg != "" {
826					t.Errorf("view %q: %s (A-16 criterion 5)\n%s", vt, msg, ansi.Strip(fr.RenderFooter(120)))
827				}
828			})
829		}
830	}
831	
832	// The footer logic, on fictitious data.
833	func TestActivityGuardFooterLogic(t *testing.T) {
834		seed := func(*testing.T, *App) indicator.State { return indicator.Running }
835		const v command.ViewType = "fiction"
836		mig := map[command.ViewType][]string{v: {"x"}}
837	
838		if got := footerSeedProblems(mig, nil); len(got) != 1 || !strings.Contains(got[0], `"fiction"`) {
839			t.Errorf("a migrated view without a seed: %v", got)
840		}
841		if got := footerSeedProblems(nil, map[command.ViewType]func(*testing.T, *App) indicator.State{v: seed}); len(got) != 1 {
842			t.Errorf("a seed without a migrated view: %v", got)
843		}
844		if got := footerSeedProblems(mig, map[command.ViewType]func(*testing.T, *App) indicator.State{v: seed}); len(got) != 0 {
845			t.Errorf("a seeded migrated view: %v", got)
846		}
847	
848		run := indicator.Glyph(indicator.Running, true)
849		if msg := footerGlyphProblem("  Scanning "+run+" a", indicator.Running); msg != "" {
850			t.Errorf("a footer with the glyph: %s", msg)
851		}
852		if msg := footerGlyphProblem("  1 job running", indicator.Running); msg == "" {
853			t.Error("a footer without the glyph passed")
854		}
855		if msg := footerGlyphProblem("anything", indicator.Idle); msg == "" {
856			t.Error("an idle seed passed: it has no glyph to look for")
857		}
858	}
